            (8, 3),
            (9, 4),
            (10, 5),
            (15, 8),
            (100, 31),
        ]
        correct_count = 0
        for input_n, expected_output in test_cases:
            actual_output = get_max_generated_array(input_n)
            if actual_output == expected_output:
                print('True')
                correct_count += 1
            else:
                print('False')
        print(f"{correct_count}/{len(test_cases)}")

    run_tests()

