        ([10,20,20,10,10,30,50,10,20], False),
        ([1,2,3,4,5], True),
        ([1], True),
        ([], True) # Empty array should return true as there are no occurrences to compare
    ]

    correct_tests = 0
    total_tests = len(test_cases)

    for i, (input_arr, expected_output) in enumerate(test_cases):
        actual_output = unique_occurrences(input_arr)
        if actual_output == expected_output:
            print(True)
            correct_tests += 1
        else:
            print(False)

    print(f"{correct_tests}/{total_tests}")

if __name__ == '__main__':
    run_tests()

class MyCalendarTwo:
    def __init__(self):
        self.booked = []
        self.double_booked = []

    def book(self, start: int, end: int) -> bool:
        for db_start, db_end in self.double_booked:
            intersection_start = max(db_start, start)
            intersection_end = min(db_end, end)
            if intersection_start < intersection_end:
                return False

        current_double_booked = []
        for b_start, b_end in self.booked:
            intersection_start = max(b_start, start)
            intersection_end = min(b_end, end)
            if intersection_start < intersection_end:
                current_double_booked.append((intersection_start, intersection_end))

        self.double_booked.extend(current_double_booked)
        self.booked.append((start, end))
        return True

