def subarrays_divisible_by_k(A, K):
    count = 0
    n = len(A)
    for i in range(n):
        for j in range(i, n):
            subarray = A[i:j+1]
            subarray_sum = sum(subarray)
            if subarray_sum % K == 0:
                count += 1
    return count

