        ([[4,9,2],[3,5,7],[8,1,6]], 1),
        ([[4,9,2,4],[3,5,7,3],[8,1,6,8],[4,9,2,4]], 1),
        ([[7,0,5],[2,4,6],[3,8,1]], 0),
        ([[10,3,5],[1,6,12],[7,9,2]], 0)
