def solve():
    def find_max_value(points, k):
        max_val = -float('inf')
        n = len(points)
        for i in range(n):
            for j in range(i + 1, n):
                xi, yi = points[i]
                xj, yj = points[j]
                if abs(xi - xj) <= k:
                    current_val = yi + yj + abs(xi - xj)
                    max_val = max(max_val, current_val)
        return max_val

    def run_test(points, k, expected_output):
        output = find_max_value(points, k)
        if output == expected_output:
            print('True')
            return True
        else:
            print('False')
            return False

