class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def treeToDoublyList(root):
    if not root:
        return None

    head = None
    prev = None

    def inorder(node):
        nonlocal head, prev
        if not node:
            return

        inorder(node.left)

        if not prev:
            head = node
        else:
            prev.right = node
            node.left = prev
        prev = node

        inorder(node.right)

    inorder(root)

    if head:
        head.left = prev
        prev.right = head

    return head

def bst_from_list(lst):
    if not lst:
        return None
    root = Node(lst[0])
    nodes = [root]
    i = 1
    while i < len(lst):
        node = nodes.pop(0)
        if lst[i] is not None:
            node.left = Node(lst[i])
            nodes.append(node.left)
        i += 1
        if i < len(lst) and lst[i] is not None:
            node.right = Node(lst[i])
            nodes.append(node.right)
        i += 1
    return root

def doubly_list_to_list(head):
    if not head:
        return []
    res = []
    curr = head
    while True:
        res.append(curr.val)
        curr = curr.right
        if curr == head:
            break
    return res

