def flip_game(currentState):
    possible_states = []
    for i in range(len(currentState) - 1):
        if currentState[i:i+2] == "++":
            new_state = list(currentState)
            new_state[i:i+2] = "--"
            possible_states.append("".join(new_state))
    return possible_states

