def longest_line_of_ones(matrix):
    if not matrix or not matrix[0]:
        return 0

    rows = len(matrix)
    cols = len(matrix[0])
    max_length = 0

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 1:
                # Horizontal
                count = 0
                for k in range(j, cols):
                    if matrix[i][k] == 1:
                        count += 1
                    else:
                        break
                max_length = max(max_length, count)

                # Vertical
                count = 0
                for k in range(i, rows):
                    if matrix[k][j] == 1:
                        count += 1
                    else:
                        break
                max_length = max(max_length, count)

                # Diagonal
                count = 0
                for k in range(min(rows - i, cols - j)):
                    if matrix[i + k][j + k] == 1:
                        count += 1
                    else:
                        break
                max_length = max(max_length, count)

                # Anti-diagonal
                count = 0
                for k in range(min(rows - i, j + 1)):
                    if matrix[i + k][j - k] == 1:
                        count += 1
                    else:
                        break
                max_length = max(max_length, count)

    return max_length

