def get_possible_jumps(arr, d, i):
    jumps = []
    for x in range(1, d + 1):
        # forward jump
        j = i + x
        if j < len(arr):
            if arr[i] > arr[j]:
                valid_jump = True
                for k in range(min(i, j) + 1, max(i, j)):
                    if arr[i] <= arr[k]:
                        valid_jump = False
                        break
                if valid_jump:
                    jumps.append(j)
        # backward jump
        j = i - x
        if j >= 0:
            if arr[i] > arr[j]:
                valid_jump = True
                for k in range(min(i, j) + 1, max(i, j)):
                    if arr[i] <= arr[k]:
                        valid_jump = False
                        break
                if valid_jump:
                    jumps.append(j)
    return jumps

def solve(arr, d, i, memo):
    if i in memo:
        return memo[i]
    max_count = 1
    for j in get_possible_jumps(arr, d, i):
        max_count = max(max_count, 1 + solve(arr, d, j, memo))
    memo[i] = max_count
    return max_count

def max_indices_visited(arr, d):
    max_indices = 0
    for i in range(len(arr)):
        max_indices = max(max_indices, solve(arr, d, i, {}))
    return max_indices

