def isMatch(s: str, p: str) -> bool:
    memo = {}

    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]

        if j == len(p):
            return i == len(s)

        if j + 1 < len(p) and p[j + 1] == '*':
            if i < len(s) and (p[j] == s[i] or p[j] == '.'):
                res = dp(i + 1, j) or dp(i, j + 2)
            else:
                res = dp(i, j + 2)
        else:
            if i < len(s) and (p[j] == s[i] or p[j] == '.'):
                res = dp(i + 1, j + 1)
            else:
                res = False

        memo[(i, j)] = res
        return res

    return dp(0, 0)

