def eraseOverlapIntervals(intervals):
    if not intervals:
        return 0
    intervals.sort(key=lambda x: (x[1], x[0]))
    removed_count = 0
    last_end_time = float('-inf')
    for interval in intervals:
        start, end = interval
        if start >= last_end_time:
            last_end_time = end
        else:
            removed_count += 1
    return removed_count

