def solve():
    def candy(ratings):
        n = len(ratings)
        candies = [1] * n

        for i in range(1, n):
            if ratings[i] > ratings[i-1]:
                candies[i] = candies[i-1] + 1

        for i in range(n - 2, -1, -1):
            if ratings[i] > ratings[i+1]:
                candies[i] = max(candies[i], candies[i+1] + 1)

        return sum(candies)

    test_cases = [
        {"ratings": [1, 0, 2], "expected": 5},
        {"ratings": [1, 2, 2], "expected": 4},
        {"ratings": [1, 2, 3, 4, 5], "expected": 15},
        {"ratings": [5, 4, 3, 2, 1], "expected": 15},
        {"ratings": [1, 1, 1, 1, 1], "expected": 5},
        {"ratings": [2, 1, 0, 1, 2], "expected": 9},
        {"ratings": [0], "expected": 1},
        {"ratings": [1, 1, 2], "expected": 4},
        {"ratings": [1, 2, 1], "expected": 4},
        {"ratings": [2, 2, 1], "expected": 4},
    ]

    correct_tests = 0
    for i, case in enumerate(test_cases):
        result = candy(case["ratings"])
        if result == case["expected"]:
            print(True)
            correct_tests += 1
        else:
            print(False)
            print(f"Test case {i+1} failed: Input={case['ratings']}, Expected={case['expected']}, Got={result}")

    print(f"{correct_tests}/{len(test_cases)}")

solve()

def count_trailing_zeros_factorial(x):
    count = 0
    i = 5
    while x // i >= 1:
        count += x // i
        i *= 5
    return count

def solve():
    k_values = [0, 5]
    expected_outputs = [5, 0]

    num_tests = len(k_values)
    correct_tests = 0

    for i in range(num_tests):
        k = k_values[i]
        expected_output = expected_outputs[i]

        low = 0
        high = max(5 * k + 1, 5)
        x_start = -1

        while low <= high:
            mid = (low + high) // 2
            zeros = count_trailing_zeros_factorial(mid)
            if zeros >= k:
                x_start = mid
                high = mid - 1
            else:
                low = mid + 1

        if x_start != -1 and count_trailing_zeros_factorial(x_start) == k:
            actual_output = 5
        else:
            actual_output = 0

        if actual_output == expected_output:
            print('True')
            correct_tests += 1
        else:
            print('False')

    print(f"{correct_tests}/{num_tests}")

if __name__ == '__main__':
    solve()

def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token == '+':
            operand2 = stack.pop()
            operand1 = stack.pop()
            stack.append(operand1 + operand2)
        elif token == '-':
            operand2 = stack.pop()
            operand1 = stack.pop()
            stack.append(operand1 - operand2)
        elif token == '*':
            operand2 = stack.pop()
            operand1 = stack.pop()
            stack.append(operand1 * operand2)
        elif token == '/':
            operand2 = stack.pop()
            operand1 = stack.pop()
            stack.append(int(operand1 / operand2))
        else:
            stack.append(int(token))
    return stack[0]

