def is_valid_start_value(startValue, nums):
  current_sum = startValue
  for num in nums:
    current_sum += num
    if current_sum < 1:
      return False
  return True

def min_start_value(nums):
  startValue = 1
  while True:
    if is_valid_start_value(startValue, nums):
      return startValue
    startValue += 1

