def solve_board(board):
    if not board or not board[0]:
        return board
    m = len(board)
    n = len(board[0])

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != 'O':
            return
        board[i][j] = 'S'
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    # Iterate through the border
    for j in range(n):
        if board[0][j] == 'O':
            dfs(0, j)
        if board[m - 1][j] == 'O':
            dfs(m - 1, j)
    for i in range(m):
        if board[i][0] == 'O':
            dfs(i, 0)
        if board[i][n - 1] == 'O':
            dfs(i, n - 1)

    # Capture 'O' regions and restore 'S' regions
    for i in range(m):
        for j in range(n):
            if board[i][j] == 'O':
                board[i][j] = 'X'
            elif board[i][j] == 'S':
                board[i][j] = 'O'
    return board

