class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def treeToDoublyList(root):
    if not root:
        return None

    head = None
    prev = None

    def inorder(node):
        nonlocal head, prev
        if not node:
            return

        inorder(node.left)

        if not prev:
            head = node
        else:
            prev.right = node
            node.left = prev
        prev = node

        inorder(node.right)

    inorder(root)

    if head:
        head.left = prev
        prev.right = head

    return head

def construct_bst(nodes):
    if not nodes:
        return None
    root = Node(nodes[0])
    queue = [root]
    i = 1
    while queue and i < len(nodes):
        current_node = queue.pop(0)
        if nodes[i] is not None:
            current_node.left = Node(nodes[i])
            queue.append(current_node.left)
        i += 1
        if i < len(nodes) and nodes[i] is not None:
            current_node.right = Node(nodes[i])
            queue.append(current_node.right)
        i += 1
    return root

def doubly_list_to_array(head):
    if not head:
        return []
    result = []
    curr = head
    while True:
        result.append(curr.val)
        curr = curr.right
        if curr == head:
            break
    return result

def run_test(input_tree, expected_output):
    root = construct_bst(input_tree)
    head = treeToDoublyList(root)
    output_list = doubly_list_to_array(head)
    return output_list == expected_output

